import {perspectives,storyBranches,storyClosings,storyEnding} from './reflection.mjs';
// Closure-only story state. Replacing this activity (pause/leave/reload) discards choices.
export function renderReflection(root,finish){
 let page=0,perspective=null,branch=null,action=null,closing=null;
 const art=()=>`<svg class="story-art" viewBox="0 0 320 150" aria-hidden="true" focusable="false"><path d="M15 133h290" stroke="#284b46" stroke-width="3"/><g stroke="#284b46" stroke-width="3"><rect x="112" y="99" width="38" height="32" rx="4" fill="#d5ad65"/><rect x="157" y="99" width="38" height="32" rx="4" fill="#98b1a0"/><rect x="130" y="65" width="38" height="32" rx="4" fill="#b3c6d3"/><rect x="204" y="103" width="38" height="26" rx="4" fill="#d5ad65" transform="rotate(-12 223 116)"/><circle cx="57" cy="52" r="17" fill="#d8b9a0"/><path d="M34 116V89q23-25 46 0v27" fill="#91a17b"/><circle cx="271" cy="52" r="17" fill="#bc936b"/><path d="M251 116V89q20-25 40 0v27" fill="#8faab8"/></g></svg>`;
 const draw=(moveFocus=false)=>{
 let content='';
 if(page===0)content=`<h4 id="reflection-title" tabindex="-1">La torre de Dani</h4><p>Dani construye una torre de bloques grandes. La torre se cae antes de poder enseñarla. Sam pregunta: «¿Quieres compañía o prefieres un momento?».</p><fieldset><legend>¿Qué podría sentir Dani? Puedes explorar varias ideas.</legend><div class="answer-options">${perspectives.map(p=>`<button type="button" class="answer-option" data-perspective="${p.id}" aria-pressed="${p.id===perspective}">${p.label}</button>`).join('')}</div></fieldset><div id="reflection-feedback" class="feedback" role="status" aria-live="polite" aria-atomic="true">${perspective?perspectives.find(p=>p.id===perspective).why+' No hay puntuación ni una única emoción correcta.':''}</div><button type="button" class="action primary" id="reflection-continue">Imaginar qué hace Dani</button><p class="quiet">También puedes continuar sin elegir una emoción.</p>`;
 if(page===1)content=`<h4 id="reflection-title" tabindex="-1">Dani puede elegir el siguiente paso</h4><p>No sabemos qué preferiría cada persona. Elige una posibilidad para esta historia; cada camino continúa de forma distinta.</p><div class="answer-options">${Object.entries(storyBranches).map(([id,b])=>`<button type="button" class="answer-option" data-story-branch="${id}">${b.label}</button>`).join('')}</div>`;
 if(page===2){const b=storyBranches[branch];content=`<h4 id="reflection-title" tabindex="-1">${b.label}</h4><p class="story-consequence">${b.scene}</p><fieldset><legend>${b.question}</legend><div class="answer-options">${b.options.map(o=>`<button type="button" class="answer-option" data-story-action="${o.id}">${o.label}</button>`).join('')}</div></fieldset>`;}
 if(page===3){const a=storyBranches[branch].options.find(o=>o.id===action);content=`<h4 id="reflection-title" tabindex="-1">Tu elección cambia la escena</h4><p class="story-consequence">${a.result}</p><fieldset><legend>¿Cómo cerramos esta versión?</legend><div class="answer-options">${storyClosings.map(o=>`<button type="button" class="answer-option" data-story-closing="${o.id}">${o.label}</button>`).join('')}</div></fieldset>`;}
 if(page===4){const end=storyEnding(branch,action,closing);content=`<h4 id="reflection-title" tabindex="-1">${end.title}</h4><p class="story-consequence" id="story-ending">${end.text}</p><p>${end.question}</p><button type="button" class="action secondary" id="story-explore">Opcional: explorar otro camino</button>`;}
 root.innerHTML=`<div class="story-studio"><p class="eyebrow">IMAGINAR · DECIDIR · VER QUÉ CAMBIA</p>${art()}<p class="quiet">${page<4?'Momento '+(page+1)+' de 4':'Un final posible'} · Historia ficticia, sin puntuación. No hace falta hablar de ti.</p>${content}<div class="controls">${page>0?'<button type="button" class="action secondary" id="story-back">Volver a la decisión anterior</button>':''}<button type="button" class="action secondary" id="reflection-draw">Imaginar otro final fuera de pantalla</button><button type="button" class="action secondary" id="reflection-pass">Prefiero no responder · cerrar</button></div><details><summary>Una ayuda para quien acompaña</summary><p>¿Ayudar siempre significa hacer algo o a veces esperar? Pregunta por las razones del personaje sin pedir vivencias íntimas ni imponer una respuesta moral. No interpretamos sentimientos ni ofrecemos terapia.</p></details><p class="quiet">Las decisiones solo están en esta escena. Al pausar, salir o recargar se limpian; después podrás empezar otra versión. Solo se guarda si la sesión está abierta, en pausa o cerrada.</p></div>`;
 const on=(selector,fn)=>root.querySelector(selector)?.addEventListener('click',fn);
 root.querySelectorAll('[data-perspective]').forEach(b=>b.addEventListener('click',()=>{perspective=b.dataset.perspective;draw();root.querySelector(`[data-perspective="${perspective}"]`).focus();}));
 on('#reflection-continue',()=>{page=1;draw(true);});
 root.querySelectorAll('[data-story-branch]').forEach(b=>b.addEventListener('click',()=>{branch=b.dataset.storyBranch;action=null;closing=null;page=2;draw(true);}));
 root.querySelectorAll('[data-story-action]').forEach(b=>b.addEventListener('click',()=>{action=b.dataset.storyAction;closing=null;page=3;draw(true);}));
 root.querySelectorAll('[data-story-closing]').forEach(b=>b.addEventListener('click',()=>{closing=b.dataset.storyClosing;page=4;draw(true);}));
 on('#story-back',()=>{page--;draw(true);});on('#story-explore',()=>{page=1;branch=null;action=null;closing=null;draw(true);});
 on('#reflection-draw',finish);on('#reflection-pass',finish);
 if(moveFocus)root.querySelector('#reflection-title').focus();
 };
 draw();
}
